import pandas as pd
import seaborn as sns
from sklearn.preprocessing import StandardScaler

def task_func(df1, df2):
    # Merge the dataframes on 'id' using an outer join
    merged_df = pd.merge(df1, df2, on='id', how='outer')

    # Identify numeric features from df1, excluding 'id'
    num_cols_df1 = [col for col in df1.select_dtypes(include='number').columns if col != 'id']

    # Determine the column names in the merged dataframe (handling potential overlaps that get the '_x' suffix)
    scaled_cols = []
    for col in num_cols_df1:
        target_col = col if col in merged_df.columns else f"{col}_x"
        if target_col in merged_df.columns:
            scaled_cols.append(target_col)

    # Scale the identified numeric features
    if scaled_cols:
        scaler = StandardScaler()
        # If there are no missing values, apply fit_transform directly to the subset
        if not merged_df[scaled_cols].isna().any().any():
            merged_df[scaled_cols] = scaler.fit_transform(merged_df[scaled_cols])
        else:
            # If NaNs are present (e.g., due to outer join), scale each column individually on non-NaN rows
            for col in scaled_cols:
                not_nan = merged_df[col].notna()
                if not_nan.any():
                    merged_df.loc[not_nan, col] = scaler.fit_transform(merged_df.loc[not_nan, [col]])[:, 0]

    # Generate a pair plot for the scaled features
    if scaled_cols:
        pair_plot = sns.pairplot(merged_df[scaled_cols])
    else:
        # Fallback to prevent seaborn errors if no numeric columns from df1 were found
        pair_plot = sns.pairplot(pd.DataFrame({'dummy': [0]}))

    return merged_df, pair_plot

